-- Frozen car_rental dataset. Generated once from the original
-- generative seed, then committed verbatim so that every engine and
-- every PostgreSQL version loads byte-identical rows. random()/setseed()
-- are deliberately not used here: PostgreSQL 16 changed its PRNG, so a
-- generative seed yields different data on PG15 vs PG16 and the
-- cross-engine comparison would be confounded by the data itself.


-- locations (10 rows)

-- vehicle_categories (5 rows)

-- clients (600 rows)

-- employees (40 rows)

-- vehicles (80 rows)

-- reservations (3000 rows)

-- payments (2691 rows)

-- maintenance_records (400 rows)

-- reviews (1200 rows)

-- Resync sequences past the explicit ids inserted above
SELECT setval(pg_get_serial_sequence('locations','id'), (SELECT MAX(id) FROM locations));
SELECT setval(pg_get_serial_sequence('vehicle_categories','id'), (SELECT MAX(id) FROM vehicle_categories));
SELECT setval(pg_get_serial_sequence('clients','id'), (SELECT MAX(id) FROM clients));
SELECT setval(pg_get_serial_sequence('employees','id'), (SELECT MAX(id) FROM employees));
SELECT setval(pg_get_serial_sequence('vehicles','id'), (SELECT MAX(id) FROM vehicles));
SELECT setval(pg_get_serial_sequence('reservations','id'), (SELECT MAX(id) FROM reservations));
SELECT setval(pg_get_serial_sequence('payments','id'), (SELECT MAX(id) FROM payments));
SELECT setval(pg_get_serial_sequence('maintenance_records','id'), (SELECT MAX(id) FROM maintenance_records));
SELECT setval(pg_get_serial_sequence('reviews','id'), (SELECT MAX(id) FROM reviews));
